import { MapContainer, TileLayer } from "react-leaflet";
import "leaflet/dist/leaflet.css"
import "./components/Pages/styles.css"
export default function LeafletTest() {
    const[testingData, setTestingData] = useState([])
    const[LoadindData, setLoadingData] = useState(false)

    const fetchData = async () => {
        try{
          setLoadingData(true)
          setHaveData(false)
          const response = await axios.post("https://get-uploads-86452853723.us-central1.run.app/?country=ZA&year=2021&page=1&page_size=500") //attempt to get response from backend
          //Set the LatencyData to the data that was retrieved from MLab
          setTestingData({
            labels: response.data.map((data) => data.country),
            datasets: [{
              label: "Mean Upload Speed",
              data: response.data.map((data) => data.metric),
              backgroundColor: ["#32CD32"],
              borderColor: "black",
              borderWidth: 2,
            }]
          });
          
          console.log("Fetched the data")
        } catch(e){
          console.log(e);
        }
      }

    return (
        
        <MapContainer center={[0, 17]} zoom={2}>
            <TileLayer
                url="https://api.mapbox.com/styles/v1/elouw/cm10xz51301d301pbdw8w8xa7/tiles/256/{z}/{x}/{y}@2x?access_token=pk.eyJ1IjoiZWxvdXciLCJhIjoiY20xMG5zYXN0MDdhcTJycjVoYXg3Y2VrbCJ9.m9NoEyiaJx-A2AXDHIR6Ew"
                attribution="© <a href='https://www.mapbox.com/about/maps/'>Mapbox</a> © <a href='http://www.openstreetmap.org/copyright'>OpenStreetMap</a> <strong><a href='https://labs.mapbox.com/contribute/' target='_blank'>Improve this map</a></strong>"/>
        </MapContainer>
        
    )
}
